package com.deardiary.privateapp;
import android.webkit.*;import android.widget.LinearLayout;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)@Config(sdk=28,manifest=Config.NONE,qualifiers="mdpi")@org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE)
public class InstagramPrivacyTest{
 InstagramActivity a;FakeWeb w;
 static class FakeWeb extends WebView{String loaded="";boolean stopped,paused,destroyed,blank,history,back;FakeWeb(InstagramActivity a){super(a);}@Override public boolean canGoBack(){return history;}@Override public void goBack(){back=true;}@Override public void stopLoading(){stopped=true;}@Override public void onPause(){paused=true;}@Override public void loadUrl(String u){loaded=u;blank="about:blank".equals(u);}@Override public void destroy(){destroyed=true;}}
 void set(String n,Object v)throws Exception{Field f=InstagramActivity.class.getDeclaredField(n);f.setAccessible(true);f.set(a,v);}
 @Before public void setup()throws Exception{a=Robolectric.buildActivity(InstagramActivity.class).get();w=new FakeWeb(a);new LinearLayout(a).addView(w);set("web",w);set("started",true);}
 @Test public void tabReturnKeepsWebViewAlive()throws Exception{a.setIntent(new android.content.Intent().putExtra("return_ticket","test"));set("continuous",true);Method m=InstagramActivity.class.getDeclaredMethod("returnToDiary",String.class);m.setAccessible(true);m.invoke(a,"home");a.onPause();assertFalse(w.destroyed||w.blank||w.stopped);assertFalse(a.isFinishing());android.content.Intent intent=org.robolectric.Shadows.shadowOf(a).getNextStartedActivity();assertTrue(intent.getBooleanExtra("instagram_return",false));assertTrue(intent.getBooleanExtra("continuous",false));assertEquals("test",intent.getStringExtra("return_ticket"));}
 @Test public void reopeningRetainsSameWebView()throws Exception{android.content.Intent i=new android.content.Intent().putExtra("issued",android.os.SystemClock.elapsedRealtime()).putExtra("return_ticket","fresh");a.onNewIntent(i);Field f=InstagramActivity.class.getDeclaredField("web");f.setAccessible(true);assertSame(w,f.get(a));assertFalse(w.blank||w.destroyed||w.stopped);}
 @Test public void validReelOpensInRetainedWebView()throws Exception{a.onNewIntent(new android.content.Intent().putExtra("issued",android.os.SystemClock.elapsedRealtime()).putExtra("return_ticket","fresh").putExtra("reel_url","https://instagram.com/reel/ABC_123/?igsh=tracking"));assertEquals("https://www.instagram.com/reel/ABC_123/",w.loaded);assertFalse(w.destroyed);}
 @Test public void invalidReelCannotNavigateRetainedWebView()throws Exception{a.onNewIntent(new android.content.Intent().putExtra("issued",android.os.SystemClock.elapsedRealtime()).putExtra("reel_url","https://evil.test/reel/ABC/"));assertEquals("",w.loaded);}
 @Test public void expiredLaunchCannotNavigateReel()throws Exception{a.onNewIntent(new android.content.Intent().putExtra("issued",android.os.SystemClock.elapsedRealtime()-6000).putExtra("reel_url","https://instagram.com/reel/ABC/"));assertEquals("",w.loaded);}
 @Test public void leavingInstagramInvalidatesQuickReturn()throws Exception{set("continuous",true);a.onPause();Field f=InstagramActivity.class.getDeclaredField("continuous");f.setAccessible(true);assertFalse(f.getBoolean(a));}
 @Test public void savingStateInvalidatesQuickReturn()throws Exception{set("continuous",true);a.onSaveInstanceState(new android.os.Bundle());Field f=InstagramActivity.class.getDeclaredField("continuous");f.setAccessible(true);assertFalse(f.getBoolean(a));}
 @Test public void backgroundPausesButKeepsPage()throws Exception{a.onPause();assertTrue(w.paused);assertFalse(w.stopped||w.blank||w.destroyed);assertFalse(a.isFinishing());}
 @Test public void stateSaveKeepsScreen(){a.onSaveInstanceState(new android.os.Bundle());assertFalse(w.blank||w.destroyed);assertFalse(a.isFinishing());}
 @Test public void backAtStartCloses(){a.onBackPressed();assertTrue(w.blank&&w.destroyed);}
 @Test public void noCallerCannotOpen(){InstagramActivity x=Robolectric.buildActivity(InstagramActivity.class).create().get();assertTrue(x.isFinishing());}
 @Test public void backNavigatesBeforeExit(){w.history=true;a.onBackPressed();assertTrue(w.back);assertFalse(a.isFinishing());assertFalse(w.destroyed);}
 @Test public void keyboardAndNavigationUseLargerInset(){assertEquals(300,InstagramActivity.safeBottom(24,300));assertEquals(48,InstagramActivity.safeBottom(48,0));}
 @Test public void reelsStillHasNoSecureFlag(){assertEquals(0,a.getWindow().getAttributes().flags&android.view.WindowManager.LayoutParams.FLAG_SECURE);}
 @Test public void nativeNavHasSixActions(){final String[] chosen={""};InstagramNav nav=new InstagramNav(a,false,key->chosen[0]=key);assertEquals(6,nav.getChildCount());nav.getChildAt(0).performClick();assertEquals("home",chosen[0]);nav.getChildAt(3).performClick();assertEquals("room",chosen[0]);nav.getChildAt(4).performClick();assertEquals("reels",chosen[0]);}
 @Test public void navigationTouchesWebWithoutSpacer()throws Exception{for(boolean dark:new boolean[]{false,true}){LinearLayout content=new LinearLayout(a);content.setOrientation(LinearLayout.VERTICAL);android.view.View page=new android.view.View(a);page.setBackgroundColor(android.graphics.Color.rgb(35,35,35));content.addView(page,new LinearLayout.LayoutParams(-1,0,1));InstagramNav nav=new InstagramNav(a,dark,key->{});InstagramActivity.addNavigation(content,nav);content.measure(android.view.View.MeasureSpec.makeMeasureSpec(390,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(300,1073741824));content.layout(0,0,390,300);assertEquals(page.getBottom(),nav.getTop());assertEquals(0,nav.getLeft());assertEquals(390,nav.getRight());assertEquals(300,nav.getBottom());android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(390,300,android.graphics.Bitmap.Config.ARGB_8888);content.draw(new android.graphics.Canvas(image));try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(System.getProperty("java.io.tmpdir"),"native-reels28-flush-"+(dark?"dark":"light")+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}}
 @Test public void renderNativeNav()throws Exception{for(boolean dark:new boolean[]{false,true}){InstagramNav nav=new InstagramNav(a,dark,key->{});nav.measure(android.view.View.MeasureSpec.makeMeasureSpec(390,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(76,android.view.View.MeasureSpec.EXACTLY));nav.layout(0,0,390,76);android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(390,76,android.graphics.Bitmap.Config.ARGB_8888);nav.draw(new android.graphics.Canvas(image));try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(System.getProperty("java.io.tmpdir"),"native-reels-nav-"+(dark?"dark":"light")+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}}
}
